import{_ as e,o,c as a,ai as i}from"./chunks/framework.Ci0kozOl.js";const d=JSON.parse('{"title":"Repository Pattern in UnoPim","description":"","frontmatter":{},"headers":[],"relativePath":"2.1/architecture/repository-pattern.md","filePath":"2.1/architecture/repository-pattern.md","lastUpdated":1778854311000}'),r={name:"2.1/architecture/repository-pattern.md"};function n(s,t,l,p,h,m){return o(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="repository-pattern-in-unopim" tabindex="-1">Repository Pattern in UnoPim <a class="header-anchor" href="#repository-pattern-in-unopim" aria-label="Permalink to &quot;Repository Pattern in UnoPim&quot;">​</a></h1><p>UnoPim uses the <strong>Repository Pattern</strong> to improve flexibility and maintainability in its codebase. This pattern adds an extra layer of abstraction on top of the <strong>ORM</strong>, promoting better code organization.</p><h3 id="benefits-of-the-repository-pattern" tabindex="-1">Benefits of the Repository Pattern <a class="header-anchor" href="#benefits-of-the-repository-pattern" aria-label="Permalink to &quot;Benefits of the Repository Pattern&quot;">​</a></h3><ul><li><strong>Consistency</strong>: Avoids raw queries, ensuring a consistent way to handle database operations.</li><li><strong>Maintainability</strong>: Organizes the code to make it easier to manage and update.</li><li><strong>Flexibility</strong>: Allows changes to be made without affecting other parts of the code.</li></ul><h3 id="implementation-in-unopim" tabindex="-1">Implementation in UnoPim <a class="header-anchor" href="#implementation-in-unopim" aria-label="Permalink to &quot;Implementation in UnoPim&quot;">​</a></h3><p>UnoPim implements the <strong>Repository Pattern</strong> with the <a href="https://github.com/prettus/l5-repository" target="_blank" rel="noreferrer">Prettus Repository</a> package, which offers:</p><ul><li><strong>Standardization</strong>: A consistent way to implement repositories.</li><li><strong>Extensibility</strong>: Easier customization and expansion of the application.</li><li><strong>Separation of Concerns</strong>: Clear division between business logic and data access.</li></ul><p>By using the Repository Pattern with Prettus, UnoPim ensures a more structured and adaptable architecture.</p><h2 id="eloquent-orm" tabindex="-1">Eloquent ORM <a class="header-anchor" href="#eloquent-orm" aria-label="Permalink to &quot;Eloquent ORM&quot;">​</a></h2><p><a href="https://laravel.com/docs/10.x/eloquent" target="_blank" rel="noreferrer">Eloquent</a>, the ORM in <strong>Laravel</strong>, simplifies database operations by letting developers work with objects instead of writing SQL queries, making data manipulation more intuitive.</p>',10)])])}const u=e(r,[["render",n]]);export{d as __pageData,u as default};
